sed -i '/public java.util.List<org.example.comprova.dto.QuestionDTO> getApplicationTestQuestions/i \    @Transactional\n    public void submitApplicationTest(Long applicationId, Candidate candidate) {\n        JobApplication app = jobApplicationRepository.findById(applicationId)\n                .orElseThrow(() -> new RuntimeException("Application not found"));\n        if (!app.getCandidate().getId().equals(candidate.getId())) throw new RuntimeException("Forbidden");\n        app.setStatus(org.example.comprova.enums.ApplicationStatus.EVALUATING);\n        jobApplicationRepository.save(app);\n    }\n' comprova-backend/src/main/java/org/example/comprova/service/JobPostingService.java
